import { useState, useEffect, useRef } from "react";
import "./location_box.css";
import { getAddressFromCoords, getCoordsFromAddress } from "../services/routeService";

const LABELS = ["A", "B", "C", "D", "E", "F"];

const TRANSPORT_MODES = [
  { id: "driving", label: "Ô tô", icon: "🚗" },
  { id: "motorcycle", label: "Xe máy", icon: "🏍️" },
  { id: "cycling", label: "Xe đạp", icon: "🚲" },
  { id: "foot", label: "Đi bộ", icon: "🚶" },
];

function markerColor(index, total) {
  if (index === 0) return "#22c55e";
  if (index === total - 1) return "#ef4444";
  return "#6366f1";
}

function LocationBox({ waypoints = [], setWaypoints, isOpen = false, toggle, transportMode = "driving", setTransportMode }) {
  const [locations, setLocations] = useState([]);
  const [inputValue, setInputValue] = useState("");
  const [loading, setLoading] = useState(false);
  const [dragIndex, setDragIndex] = useState(null);
  const [dragOverIndex, setDragOverIndex] = useState(null);
  const [showTransport, setShowTransport] = useState(true);
  const [showRoute, setShowRoute] = useState(true);
  const skipGeocode = useRef(false);

  useEffect(() => {
    if (skipGeocode.current) {
      skipGeocode.current = false;
      return;
    }
    if (waypoints.length > 0) {
      Promise.all(
        waypoints.map(async (point) => {
          const address = await getAddressFromCoords(point.lat, point.lng);
          return `${address} (${point.lat.toFixed(4)}, ${point.lng.toFixed(4)})`;
        })
      ).then(setLocations);
    } else {
      setLocations([]);
    }
  }, [waypoints]);

  const handleDeleteLocation = (index) => {
    setWaypoints(waypoints.filter((_, i) => i !== index));
  };

  const handleAddLocation = async () => {
    if (!inputValue.trim()) return;
    setLoading(true);
    try {
      const coords = await getCoordsFromAddress(inputValue);
      if (coords) {
        setWaypoints([...waypoints, { lat: coords.lat, lng: coords.lng }]);
        setInputValue("");
      } else {
        alert("Không tìm thấy địa điểm. Vui lòng thử lại.");
      }
    } catch (error) {
      alert("Lỗi: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleAddLocation();
  };

  const handleDragStart = (e, index) => {
    setDragIndex(index);
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", String(index));
  };

  const handleDragOver = (e, index) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    if (index !== dragIndex) setDragOverIndex(index);
  };

  const handleDragLeave = () => setDragOverIndex(null);

  const handleDrop = (e, dropIndex) => {
    e.preventDefault();
    if (dragIndex === null || dragIndex === dropIndex) {
      setDragIndex(null);
      setDragOverIndex(null);
      return;
    }
    const newWaypoints = [...waypoints];
    const newLocations = [...locations];
    const [wp] = newWaypoints.splice(dragIndex, 1);
    const [loc] = newLocations.splice(dragIndex, 1);
    newWaypoints.splice(dropIndex, 0, wp);
    newLocations.splice(dropIndex, 0, loc);
    skipGeocode.current = true;
    setLocations(newLocations);
    setWaypoints(newWaypoints);
    setDragIndex(null);
    setDragOverIndex(null);
  };

  const handleDragEnd = () => {
    setDragIndex(null);
    setDragOverIndex(null);
  };

  //nhận địa điểm hiện tại
  const getCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          const address = await getAddressFromCoords(latitude, longitude);
          setWaypoints([...waypoints, { lat: latitude, lng: longitude }]);
        }
      );
    } else {
      alert("Trình duyệt của bạn không hỗ trợ định vị.");
    }
  };  //nhận địa điểm hiện tại
  const getCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          const address = await getAddressFromCoords(latitude, longitude);
          setWaypoints([...waypoints, { lat: latitude, lng: longitude }]);
        }
      );
    } else {
      alert("Trình duyệt của bạn không hỗ trợ định vị.");
    }
  };
  const total = locations.length;

  return (
    <div className="lbox">
      {/* Nút lấy địa điểm hiện tại */}
      <button onClick={getCurrentLocation} className="btn-current-location">
        📍 Vị trí hiện tại
      </button>

      {/* ── Search bar ── */}
      <div className="lbox-search">
        <button
          className={`lbox-toggle${isOpen ? " is-open" : ""}`}
          onClick={toggle}
          title={isOpen ? "Đóng menu" : "Mở menu"}
          aria-label={isOpen ? "Đóng menu" : "Mở menu"}
        >
          {isOpen ? "✖" : "☰"}
        </button>

        <svg className="lbox-search-svg" viewBox="0 0 24 24" fill="none">
          <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="2" />
          <path d="M16.5 16.5L21 21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
        </svg>

        <input
          type="text"
          className="lbox-input"
          placeholder="Tìm địa điểm..."
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={handleKeyPress}
          disabled={loading}
          aria-label="Nhập địa điểm"
        />

        {inputValue && !loading && (
          <button
            className="lbox-clear-input"
            onClick={() => setInputValue("")}
            tabIndex={-1}
            aria-label="Xóa ô nhập"
          >
            <svg viewBox="0 0 24 24" fill="none">
              <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        )}

        <button
          className="lbox-add-btn"
          onClick={handleAddLocation}
          disabled={loading || !inputValue.trim()}
          title="Thêm điểm"
          aria-label="Thêm địa điểm"
        >
          {loading ? (
            <span className="lbox-spinner" aria-hidden="true" />
          ) : (
            <svg viewBox="0 0 24 24" fill="none">
              <path d="M12 5v14M5 12h14" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
            </svg>
          )}
        </button>
      </div>

      {/* ── Transport mode selector ── */}
      <div className="lbox-section-head" onClick={() => setShowTransport(v => !v)}>
        <span className="lbox-section-title">🚗 Phương tiện</span>
        <span className={`lbox-chevron${showTransport ? " is-open" : ""}`}>&#8250;</span>
      </div>
      <div className={`lbox-section-body${showTransport ? "" : " is-collapsed"}`}>
        <div className="lbox-transport">
          {TRANSPORT_MODES.map(mode => (
            <button
              key={mode.id}
              className={`lbox-transport-btn${transportMode === mode.id ? " is-active" : ""}`}
              onClick={(e) => { e.stopPropagation(); setTransportMode(mode.id); }}
              title={mode.label}
            >
              <span className="lbox-transport-icon">{mode.icon}</span>
              <span className="lbox-transport-label">{mode.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* ── Waypoint list ── */}
      {total > 0 && (
        <div className="lbox-route">

          <div className="lbox-section-head" onClick={() => setShowRoute(v => !v)}>
            <span className="lbox-section-title">Hành trình</span>
            <span className="lbox-route-badge">{total} điểm</span>
            <span className={`lbox-chevron${showRoute ? " is-open" : ""}`}>&#8250;</span>
          </div>

          <div className={`lbox-section-body${showRoute ? "" : " is-collapsed"}`}>

            <ul className="lbox-list" aria-label="Danh sách điểm dừng">
              {locations.map((loc, index) => (
                <li
                  key={index}
                  className={`lbox-wp${dragIndex === index ? " is-dragging" : ""}${dragOverIndex === index && dragIndex !== index ? " is-drag-over" : ""}`}
                  draggable
                  onDragStart={(e) => handleDragStart(e, index)}
                  onDragOver={(e) => handleDragOver(e, index)}
                  onDragLeave={handleDragLeave}
                  onDrop={(e) => handleDrop(e, index)}
                  onDragEnd={handleDragEnd}
                >

                  {/* Left column: marker + line */}
                  <div className="lbox-wp-track">
                    <div
                      className="lbox-wp-dot"
                      style={{ background: markerColor(index, total) }}
                      aria-hidden="true"
                    >
                      {LABELS[index] ?? index + 1}
                    </div>
                    {index < total - 1 && (
                      <div className="lbox-wp-line" aria-hidden="true" />
                    )}
                  </div>

                  {/* Text */}
                  <div className="lbox-wp-info">
                    <span className="lbox-wp-tag">
                      {index === 0
                        ? "Điểm đầu"
                        : index === total - 1
                          ? "Điểm cuối"
                          : `Điểm ${index + 1}`}
                    </span>
                    <span className="lbox-wp-addr">{loc}</span>
                  </div>

                  {/* Drag handle */}
                  <div className="lbox-drag-handle" aria-hidden="true">
                    <svg viewBox="0 0 10 16" width="10" height="16">
                      <circle cx="3" cy="3" r="1.5" fill="currentColor" />
                      <circle cx="7" cy="3" r="1.5" fill="currentColor" />
                      <circle cx="3" cy="8" r="1.5" fill="currentColor" />
                      <circle cx="7" cy="8" r="1.5" fill="currentColor" />
                      <circle cx="3" cy="13" r="1.5" fill="currentColor" />
                      <circle cx="7" cy="13" r="1.5" fill="currentColor" />
                    </svg>
                  </div>

                  {/* Delete */}
                  <button
                    className="lbox-wp-del"
                    onClick={() => handleDeleteLocation(index)}
                    title="Xóa điểm này"
                    aria-label={`Xóa điểm ${LABELS[index] ?? index + 1}`}
                  >
                    <svg viewBox="0 0 24 24" fill="none">
                      <path d="M18 6L6 18M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                  </button>

                </li>
              ))}
            </ul>

            <div className="lbox-footer">
              <button
                className="lbox-start-btn"
                disabled={waypoints.length < 2}
                title={waypoints.length < 2 ? "Chọn ít nhất 2 điểm" : "Bắt đầu di chuyển"}
              >
                <svg viewBox="0 0 24 24" fill="none" width="15" height="15">
                  <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" fill="currentColor" />
                </svg>
                Bắt đầu di chuyển
              </button>
            </div>

          </div>{/* end lbox-section-body */}

        </div>
      )}
    </div>
  );
}

export default LocationBox;

import { MapContainer, TileLayer, Marker, Popup, useMapEvents, Polyline } from 'react-leaflet';
import 'leaflet/dist/leaflet.css'; // Quan trọng: Để hiện thị các mảnh bản đồ
import { useState, useEffect } from 'react';
import './mapomponent.css';
import { calculateRoute, calculateOptimisticRoute } from '../services/routeService';

// Thành phần xử lý tương tác click
function LocationMarker({ waypoints, onSelectMarker }) {
    const map = useMapEvents({
        dblclick(e) {
            onSelectMarker(e.latlng); // Gửi tọa độ ra ngoài
            map.flyTo(e.latlng, map.getZoom()); // Hiệu ứng di chuyển mượt mà
        },
    });

    return (
        <>
            {waypoints.map((point, index) => (
                <Marker key={index} position={[point.lat, point.lng]}>
                    <Popup>
                        {index === 0 ? "🟢 Điểm bắt đầu" : `📍 Điểm ${index}`}
                        <br />
                        ({point.lat.toFixed(4)}, {point.lng.toFixed(4)})
                    </Popup>
                </Marker>
            ))}
        </>
    );
}

const MapComponent = ({ waypoints = [], setWaypoints, transportMode = "driving", onRouteCalculated, onLoadingChange }) => {
    const center = [21.0285, 105.8542]; // Tọa độ mặc định Hà Nội
    const [route, setRoute] = useState(null);
    const [loading, setLoading] = useState(false);

    // Xử lý thêm marker khi click trên bản đồ
    const handleSelectMarker = (latlng) => {
        const newWaypoint = { lat: latlng.lat, lng: latlng.lng };
        setWaypoints([...waypoints, newWaypoint]);
    };

    // Gọi API tính toán đường đi khi có ≥ 2 waypoints
    useEffect(() => {
        if (waypoints.length >= 2) {
            const fetchRoute = async () => {
                setLoading(true);
                if (onLoadingChange) onLoadingChange(true);

                // 1. Cập nhật UI nhanh (Optimistic) trong lúc chờ Backend API
                try {
                    const optimisticData = await calculateOptimisticRoute(waypoints, transportMode);
                    if (optimisticData) {
                        setRoute(optimisticData);
                        if (onRouteCalculated) {
                            onRouteCalculated(optimisticData);
                        }
                    }
                } catch (e) {
                    console.error("Optimistic route error:", e);
                }

                // 2. Gọi Backend thật lấy thêm TT Thời tiết + cảnh báo
                try {
                    const routeData = await calculateRoute(waypoints, transportMode);
                    if (routeData) {
                        setRoute(routeData);
                        if (onRouteCalculated) {
                            onRouteCalculated(routeData);
                        }
                    } else {
                        console.warn("Backend failed to calculate detailed route. Keep optimistic UI.");
                    }
                } catch (error) {
                    console.error("Lỗi tính toán đường đi:", error);
                } finally {
                    setLoading(false);
                    if (onLoadingChange) onLoadingChange(false);
                }
            };
            fetchRoute();
        } else {
            setRoute(null);
            if (onRouteCalculated) onRouteCalculated(null);
            if (onLoadingChange) onLoadingChange(false);
        }
    }, [waypoints, transportMode]);

    return (
        <div className="mapomponent">
            <MapContainer center={center} zoom={7} style={{ height: '100%', width: '100%' }}
                doubleClickZoom={false}
                whenReady={(mapInstance) => {
                    mapInstance.target.invalidateSize();
                }}>
                <TileLayer
                    url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                    attribution='&copy; OpenStreetMap contributors'
                />

                <LocationMarker waypoints={waypoints} onSelectMarker={handleSelectMarker} />

                {/* Hiển thị đường route */}
                {route && route.route_points && (
                    <Polyline
                        positions={route.route_points}
                        color="blue"
                        weight={4}
                        opacity={0.7}
                    />
                )}
            </MapContainer>

            {/* Loading indicator */}
            {loading && <div className="loading">Tính toán đường đi...</div>}
        </div>
    );
};

export default MapComponent;

const addressCache = new Map();
const pendingRequests = new Map();
let nominatimLock = Promise.resolve();

/**
 * Convert coordinates (lat, lng) to address using OpenStreetMap Nominatim
 */
export async function getAddressFromCoords(lat, lng) {
  const key = `${lat.toFixed(4)},${lng.toFixed(4)}`;
  if (addressCache.has(key)) return addressCache.get(key);

  const fetchAddress = async () => {
    await nominatimLock;
    let releaseLock;
    nominatimLock = new Promise(resolve => { releaseLock = resolve; });

    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`
      );
      const data = await response.json();
      const address = data.address?.road || data.address?.city || data.display_name || key;
      addressCache.set(key, address);
      return address;
    } catch (error) {
      console.error("Error getting address from coordinates:", error);
      return key;
    } finally {
      setTimeout(releaseLock, 1000); // Enforce 1 second delay between Nominatim calls
    }
  };

  if (!pendingRequests.has(key)) {
    pendingRequests.set(key, fetchAddress().finally(() => pendingRequests.delete(key)));
  }
  return pendingRequests.get(key);
}

/**
 * Convert address to coordinates using OpenStreetMap Nominatim
 */
export async function getCoordsFromAddress(address) {
  try {
    const response = await fetch(
      `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(address)}&limit=1`
    );
    const data = await response.json();

    if (data && data.length > 0) {
      return {
        lat: parseFloat(data[0].lat),
        lng: parseFloat(data[0].lon)
      };
    }
    return null;
  } catch (error) {
    console.error("Error getting coordinates from address:", error);
    return null;
  }
}

/**
 * Calculate route between waypoints using OSRM (Open Source Routing Machine)
 */
export async function calculateRoute(waypoints, transportMode = "driving") {
  try {
    if (!waypoints || waypoints.length < 2) {
      return null;
    }

    const response = await fetch('http://localhost:8000/api/navigate/multiple', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ waypoints, vehicle: transportMode }),
    });

    if (!response.ok) {
      throw new Error('Failed to calculate route from backend');
    }

    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Error calculating route:", error);
    return null;
  }
}

/**
 * Calculate route between waypoints using local fast OSRM request for instant feedback
 */
export async function calculateOptimisticRoute(waypoints, transportMode = "driving") {
  try {
    if (!waypoints || waypoints.length < 2) return null;
    let profile = "driving";
    if (["motorcycle", "motorbike", "bike", "cycling"].includes(transportMode)) profile = "bike";
    if (["foot", "pedestrian"].includes(transportMode)) profile = "foot";

    // Format for OSRM route API: lng,lat;lng,lat...
    const coords = waypoints.map(p => `${p.lng},${p.lat}`).join(';');
    const response = await fetch(`https://router.project-osrm.org/route/v1/${profile}/${coords}?overview=full&geometries=geojson`);
    if (!response.ok) return null;
    const data = await response.json();

    if (data.routes && data.routes.length > 0) {
      const route = data.routes[0];
      const distanceKm = route.distance / 1000;

      const speed_car = 35.0;
      const speed_motorbike = 40.0;
      const speed_bike = 15.0;
      const speed_pedestrian = 5.0;

      const formatTime = (hours) => {
        if (hours <= 0) return "0 phút";
        let totalMinutes = Math.round(hours * 60);
        if (totalMinutes === 0 && hours > 0) totalMinutes = 1;
        const h = Math.floor(totalMinutes / 60);
        const m = totalMinutes % 60;
        if (h > 0) return `${h} giờ ${m} phút`;
        return `${m} phút`;
      };

      const travelTimes = {
        car: formatTime(distanceKm / speed_car),
        motorbike: formatTime(distanceKm / speed_motorbike),
        bike: formatTime(distanceKm / speed_bike),
        pedestrian: formatTime(distanceKm / speed_pedestrian)
      };

      const route_points = route.geometry.coordinates.map(c => [c[1], c[0]]);

      const segments = [];
      if (route.legs) {
        route.legs.forEach((leg, i) => {
          const legDistKm = leg.distance / 1000;
          let speed = speed_car;
          if (profile === "bike" && ["bike", "cycling"].includes(transportMode)) speed = speed_bike;
          else if (profile === "bike") speed = speed_motorbike;
          if (profile === "foot") speed = speed_pedestrian;

          segments.push({
            distance: `${legDistKm.toFixed(1)} km`,
            time: formatTime(legDistKm / speed),
            weather: null,
            floodRisk: null
          });
        });
      }

      return {
        totalDistance: `${distanceKm.toFixed(1)} km`,
        travelTimes,
        route_points,
        segments
      };
    }
  } catch (error) {
    console.error("Optimistic route error:", error);
  }
  return null;
}
